package com.hrcoresystem.hrcore_api.modules.tenant.incidents.application.service;
import com.hrcoresystem.hrcore_api.common.exception.*; import com.hrcoresystem.hrcore_api.common.security.context.SecurityContextFacade; import com.hrcoresystem.hrcore_api.modules.governance.audit.application.service.AuditTrailService; import com.hrcoresystem.hrcore_api.modules.platform.subscriptions.application.service.TenantPlanEnforcementService; import com.hrcoresystem.hrcore_api.modules.platform.tenantsettings.application.service.*; import com.hrcoresystem.hrcore_api.modules.tenant.employees.application.service.EmploymentPeriodService; import com.hrcoresystem.hrcore_api.modules.tenant.incidents.application.dto.IncidentDtos.*; import com.hrcoresystem.hrcore_api.modules.tenant.incidents.domain.model.IncidentModels.*; import com.hrcoresystem.hrcore_api.modules.tenant.incidents.infrastructure.persistence.*; import java.time.*; import java.util.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.domain.Specification; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class IncidentService {
 private final IncidentJpaRepository incidents; private final IncidentActionJpaRepository actions; private final IncidentHistoryJpaRepository histories; private final EmploymentPeriodService periods; private final BusinessSequenceService sequences; private final TenantTimezoneService timezone; private final SecurityContextFacade security; private final TenantPlanEnforcementService plans; private final AuditTrailService audit;
 public IncidentService(IncidentJpaRepository i,IncidentActionJpaRepository a,IncidentHistoryJpaRepository h,EmploymentPeriodService p,BusinessSequenceService s,TenantTimezoneService z,SecurityContextFacade sec,TenantPlanEnforcementService plans,AuditTrailService audit){incidents=i;actions=a;histories=h;periods=p;sequences=s;timezone=z;security=sec;this.plans=plans;this.audit=audit;}
 @Transactional public IncidentResponse create(Create input){plans.assertCanOperate(); UUID period=periods.requireForDate(input.employeeId(),input.occurredAt().atZone(timezone.requiredZone()).toLocalDate()).id(); UUID actor=actor(); IncidentEntity e=new IncidentEntity(); e.setId(UUID.randomUUID());e.setEmployeeId(input.employeeId());e.setEmploymentPeriodId(period);e.setIncidentNumber(sequences.nextCode("employee_incident"));e.setIncidentType(input.incidentType());e.setSeverity(input.severity());e.setTitle(input.title().trim());e.setDescription(input.description().trim());e.setOccurredAt(input.occurredAt());e.setLocation(input.location());e.setStatus(Status.OPEN);e.setReportedBy(actor);e.setAssignedTo(input.assignedTo()); IncidentEntity saved=incidents.saveAndFlush(e); history(saved,"CREATED",null,Status.OPEN,null); audit.recordTenantEvent("INCIDENT_CREATED","EMPLOYEE_INCIDENT",saved.getId().toString(),Map.of("incidentNumber",saved.getIncidentNumber())); return response(saved); }
 @Transactional(readOnly=true) public Page<IncidentResponse> list(UUID employeeId,UUID period,Type type,Severity severity,Status status,Pageable page){plans.assertCanOperate(); Specification<IncidentEntity> s=(r,q,c)->c.conjunction(); if(employeeId!=null)s=s.and((r,q,c)->c.equal(r.get("employeeId"),employeeId));if(period!=null)s=s.and((r,q,c)->c.equal(r.get("employmentPeriodId"),period));if(type!=null)s=s.and((r,q,c)->c.equal(r.get("incidentType"),type));if(severity!=null)s=s.and((r,q,c)->c.equal(r.get("severity"),severity));if(status!=null)s=s.and((r,q,c)->c.equal(r.get("status"),status));return incidents.findAll(s,page).map(this::response);}
 @Transactional(readOnly=true) public IncidentResponse detail(UUID id){plans.assertCanOperate();return response(require(id));}
 @Transactional public IncidentResponse assign(UUID id,UUID user){IncidentEntity e=lock(id);ensureOpen(e);e.setAssignedTo(user);history(e,"ASSIGNED",e.getStatus(),e.getStatus(),null);audit.recordTenantEvent("INCIDENT_ASSIGNED","EMPLOYEE_INCIDENT",id.toString(),Map.of("assignedTo",user));return response(incidents.saveAndFlush(e));}
 @Transactional public IncidentResponse startReview(UUID id){return transition(id,Status.UNDER_REVIEW,null,"INCIDENT_REVIEW_STARTED");}
 @Transactional public IncidentResponse employeeResponse(UUID id,String text){IncidentEntity e=lock(id);if(e.getStatus()==Status.CLOSED||e.getStatus()==Status.CANCELLED)throw new BusinessException("La incidencia ya finalizó");e.setEmployeeResponse(text.trim());e.setEmployeeResponseAt(Instant.now());history(e,"RESPONSE_ADDED",e.getStatus(),e.getStatus(),text.trim());return response(incidents.saveAndFlush(e));}
 @Transactional public IncidentResponse resolve(UUID id,String comment){if(comment==null||comment.isBlank())throw new BusinessException("La resolución es obligatoria");if(actions.findByIncidentIdOrderByCreatedAtAsc(id).stream().anyMatch(a->a.getStatus()==ActionStatus.PENDING||a.getStatus()==ActionStatus.IN_PROGRESS))throw new BusinessException("No se puede resolver una incidencia con acciones pendientes");return transition(id,Status.RESOLVED,comment,"INCIDENT_RESOLVED");}
 @Transactional public IncidentResponse close(UUID id,String comment){return transition(id,Status.CLOSED,comment,"INCIDENT_CLOSED");}
 @Transactional public IncidentResponse cancel(UUID id,String comment){return transition(id,Status.CANCELLED,comment,"INCIDENT_CANCELLED");}
 @Transactional public ActionResponse addAction(UUID id,ActionCreate input){IncidentEntity incident=lock(id);if(incident.getStatus()==Status.CLOSED||incident.getStatus()==Status.CANCELLED)throw new BusinessException("La incidencia ya está cerrada");IncidentActionEntity a=new IncidentActionEntity();a.setId(UUID.randomUUID());a.setIncidentId(id);a.setActionType(input.actionType());a.setDescription(input.description().trim());a.setActionDate(input.actionDate());a.setStatus(ActionStatus.PENDING);a.setResponsibleUserId(input.responsibleUserId());a.setNotes(input.notes());ActionResponse out=action(actions.saveAndFlush(a));history(incident,"ACTION_REGISTERED",incident.getStatus(),incident.getStatus(),input.description());audit.recordTenantEvent("INCIDENT_ACTION_REGISTERED","EMPLOYEE_INCIDENT",id.toString(),Map.of("actionId",a.getId().toString()));return out;}
 @Transactional(readOnly=true) public List<ActionResponse> actions(UUID id){require(id);return actions.findByIncidentIdOrderByCreatedAtAsc(id).stream().map(this::action).toList();}
 @Transactional public ActionResponse actionStatus(UUID incidentId,UUID actionId,ActionStatus target){IncidentEntity incident=lock(incidentId);if(incident.getStatus()==Status.CLOSED||incident.getStatus()==Status.CANCELLED)throw new BusinessException("La incidencia ya está cerrada");IncidentActionEntity a=actions.lock(actionId).orElseThrow(()->new ResourceNotFoundException("Acción no encontrada"));if(!incidentId.equals(a.getIncidentId()))throw new ResourceNotFoundException("Acción no encontrada");if(a.getStatus()==ActionStatus.COMPLETED||a.getStatus()==ActionStatus.CANCELLED)throw new BusinessException("La acción ya finalizó");a.setStatus(target);if(target==ActionStatus.COMPLETED)a.setCompletedAt(Instant.now());history(incident,"STATUS_CHANGED",incident.getStatus(),incident.getStatus(),"Acción " + target + ": " + a.getDescription());return action(actions.saveAndFlush(a));}
 private IncidentResponse transition(UUID id,Status target,String comment,String event){IncidentEntity e=lock(id);Status before=e.getStatus();boolean valid=(before==Status.OPEN&&target==Status.UNDER_REVIEW)||(before==Status.UNDER_REVIEW&&(target==Status.RESOLVED||target==Status.CANCELLED))||(before==Status.RESOLVED&&target==Status.CLOSED)||(before==Status.OPEN&&target==Status.CANCELLED);if(!valid)throw new BusinessException("Transición de incidencia no permitida");e.setStatus(target);if(target==Status.RESOLVED){e.setResolution(comment);e.setResolvedAt(Instant.now());}if(target==Status.CLOSED)e.setClosedAt(Instant.now());history(e,target==Status.RESOLVED?"RESOLVED":target==Status.CLOSED?"CLOSED":target==Status.CANCELLED?"CANCELLED":"STATUS_CHANGED",before,target,comment);audit.recordTenantEvent(event,"EMPLOYEE_INCIDENT",id.toString(),Map.of("previousStatus",before.name(),"newStatus",target.name()));return response(incidents.saveAndFlush(e));}
 @Transactional(readOnly=true) public List<HistoryResponse> history(UUID id){require(id);return histories.findByIncidentIdOrderByCreatedAtAscIdAsc(id).stream().map(h->new HistoryResponse(h.getId(),h.getIncidentId(),h.getAction(),h.getPreviousStatus(),h.getNewStatus(),h.getComment(),h.getPerformedBy(),h.getCreatedAt())).toList();}
 private void history(IncidentEntity e,String action,Status previous,Status next,String comment){IncidentHistoryEntity h=new IncidentHistoryEntity();h.setIncidentId(e.getId());h.setAction(action);h.setPreviousStatus(previous==null?null:previous.name());h.setNewStatus(next==null?null:next.name());h.setComment(comment);h.setPerformedBy(actor());histories.save(h);}
 private IncidentEntity lock(UUID id){return incidents.lock(id).orElseThrow(()->new ResourceNotFoundException("Incidencia no encontrada"));}private IncidentEntity require(UUID id){return incidents.findById(id).orElseThrow(()->new ResourceNotFoundException("Incidencia no encontrada"));}private void ensureOpen(IncidentEntity e){if(e.getStatus()==Status.CLOSED||e.getStatus()==Status.CANCELLED)throw new BusinessException("La incidencia ya finalizó");}private UUID actor(){try{return UUID.fromString(security.getCurrentSubject());}catch(Exception e){throw new BusinessException("Usuario autenticado requerido");}}
 private IncidentResponse response(IncidentEntity e){return new IncidentResponse(e.getId(),e.getEmployeeId(),e.getEmploymentPeriodId(),e.getIncidentNumber(),e.getIncidentType(),e.getSeverity(),e.getTitle(),e.getDescription(),e.getOccurredAt(),e.getLocation(),e.getStatus(),e.getReportedBy(),e.getAssignedTo(),e.getEmployeeResponse(),e.getEmployeeResponseAt(),e.getResolution(),e.getResolvedAt(),e.getClosedAt(),e.getCreatedAt(),e.getUpdatedAt());}private ActionResponse action(IncidentActionEntity a){return new ActionResponse(a.getId(),a.getIncidentId(),a.getActionType(),a.getDescription(),a.getActionDate(),a.getStatus(),a.getResponsibleUserId(),a.getCompletedAt(),a.getNotes(),a.getCreatedAt(),a.getUpdatedAt());}
}
